import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        ArrayList<Double> notas = new ArrayList<>();
        while (true) {
            System.out.print("Nota (o 'fin'): ");
            String t = sc.nextLine();
            if (t.equals("fin")) {
                break;
            }
            notas.add(Double.parseDouble(t));
        }
        if (notas.size() > 0) {
            double suma = 0;
            for (double n : notas) {
                suma += n;
            }
            System.out.printf("Promedio: %.1f%n", suma / notas.size());
        } else {
            System.out.println("No cargaste notas");
        }
    }
}
